<!doctype html><html lang="de"><head><meta charset="utf-8"><title>Inventurliste</title><style>body{font:12px Arial,sans-serif;color:#111;margin:18mm}h1{margin:0 0 4px}.meta{color:#666;margin-bottom:14px}table{width:100%;border-collapse:collapse}th,td{border-bottom:1px solid #bbb;padding:7px 5px;text-align:left}th{background:#eee}.count{width:34mm}.toolbar{margin-bottom:15px}@media print{.toolbar{display:none}body{margin:10mm}}</style></head><body><div class="toolbar"><button onclick="window.print()">Drucken</button></div><h1>Inventurliste</h1><div class="meta">Stand <?php p(date('d.m.Y H:i'));?> · <?php p(count($_['materials']??[]));?> Artikel</div><table><thead><tr><th>Artikel</th><th>Bezeichnung</th><th>Lagerort</th><th>Soll</th><th>Einheit</th><th class="count">Ist / gezählt</th></tr></thead><tbody><?php foreach(($_['materials']??[]) as $m):?><tr><td><?php p($m['article_no']??'');?></td><td><?php p($m['name']??'');?></td><td><?php p($m['storage_location']??'');?></td><td><?php p(number_format((float)($m['stock_quantity']??0),3,',','.'));?></td><td><?php p($m['unit']??'');?></td><td></td></tr><?php endforeach;?></tbody></table><script>window.addEventListener('load',()=>window.print());</script></body></html>
